const q=($input.first().json.query)||{};
const topic=(q.topic||'').toString().trim();
const feedUrl=topic? 'https://news.google.com/rss/search?q='+encodeURIComponent(topic)+'&hl=ko&gl=KR&ceid=KR:ko' : 'https://news.google.com/rss?hl=ko&gl=KR&ceid=KR:ko';
return [{ json:{ feedUrl } }];

const xml=String(($input.first().json && ($input.first().json.data||$input.first().json.body))||'');
const blocks=xml.match(/<item\b[\s\S]*?<\/item>/g)||[];
const heads=[];
for(const bk of blocks){ const t=bk.match(/<title>([\s\S]*?)<\/title>/); if(t){ heads.push(t[1].replace(/<!\[CDATA\[|\]\]>/g,'').trim()); } if(heads.length>=5) break; }
return [{ json:{ headlines: heads } }];
